{
    "basicRule": {
            "Name": "projectName", //项目名称
            "ExperimentQC": //实验质控
            {
                "Items": [],
                "Use": false
            },
            "ResultRule":  //结果判定
            {
                "Items": [],
                "Use": false
            },
            "SampleQC":  //样本质控
            {
                "Items": [],
                "Use": false
            },
            "UseBasicRule": false //是否使用基本规则
        }
}

//判断2个项目的实验程序是否一致，一致时可以同时运行
{
    "project1": "projectName",
    "project2": "projectName"
}

//运行实验
{
    "series": "SNxxx", //仪器序列号
    "experimentSetting": //实验设置信息
    {
        "Block": 0,
        "PlateFile": "C:\\Users\\xxx\\xxx\\test.csv",
        "UseHotBonnet" :true,
        "TemperatureControlMode" : "1" 
    }
}

/// **特别提示**
/// **调用此接口前需先调用CheckDeviceState来更新设备的状态**
/// **当设备正在运行实验时状态会自动更新，无需频繁调用CheckDeviceState**
/// 获取自动门状态结果
/// ErrorCode = CommandExecuting    正在获取最新的设备状态，稍后再调用此接口
/// ErrorCode = DeviceStateNotFound 未获取到仪器的状态
/// ErrorCode = DeviceNotFound      未找到该仪器
/// ErrorCode = DeviceNotSupport    设备不支持此功能
/// ErrorCode = None 时可以通过APIAutoDoorStateResult的Result来正确的获取到各个自动门的状态
/// Result解释{ 未知, 打开状态, 关闭状态, 实验正在运行, 自动门正在运行,状态查询中,  出错}
/// Result    { 0,      1,      2,         3,             4,          5       , 6}
{
    "series": "SNxxx"
}

/// 打开本地实验文件，并加载到内存中，不使用时需要调用CloseExperiment关闭实验，释放内存
/// 1、OpenExperiment
/// 2、GetExperimentParamter、GetExperimentBasicInfo (修改分析参数、实验基本信息前需先获取此参数后再进行修改)
/// 3、SetExperimentParamter、SetExperimentBasicInfo、SetProjectRule
/// 4、SaveExperiment
/// 5、CloseExperiment
{
    "file":"filepath.pcr" //数据文件路径
}

//设置实验基本信息
{
    "name":"ExperimentName", //实验名称
    "info": //实验基本信息
    {
        "Auditor": "111",
        "BatchNo": "222",
        "Note": "333",
        "Operator": "444",
        "PlateNo": "555"

    }
}

//获取加载的实验数据
{
    "name":"ExperimentName" //实验名称
}

 //设置实验项目高级规则
{
    "name":"ExperimentName", //实验名称
    "projectName": "projectName",//项目名称
    "rulePath":"rulePath.dll"//高级规则文件路径,路径为空时将设置为基本规则
}

//查找外部标准曲线文件,获取标准曲线数据
{
    "stdName": "stdname" //外部标准曲线文件名,为空时获取所有
}

//保存实验的标准曲线至外部标准曲线文件中
{
    "experimentName": "experimentName", //实验名称
     "projectName": "projectName", //项目名称 为空时保存实验中所有的标准曲线
      "stdName": "stdName" //保存的外标文件名 为空时默认项目名称(项目名称为空时,文件名不起作用)
}

//设置实验的外部标准曲线
{
    "experimentName": "experimentName", //实验名称
     "projectName": "projectName", //需要设置外标的项目名称
      "stdName": "stdName" //调用的外部标准曲线文件名称
}

//获取实验运行温度
{
    "name":"experimentName" //实验名称
}
